323	async function serveAppAsset(request) {
324	  const url = new URL(request.url);
325	  if (url.hostname !== "local") return new Response(null, { status: 404 });
326	
327	  let requestPath;
328	  try {
329	    requestPath = decodeURIComponent(url.pathname);
330	  } catch {
331	    return new Response(null, { status: 400 });
332	  }
333	  if (requestPath === "/" || requestPath.endsWith("/")) requestPath += "index.html";
334	
335	  const libraryAssetPrefix = "/library-assets/";
336	  const isLibraryAsset = requestPath.startsWith(libraryAssetPrefix);
337	  const assetDirectory = isLibraryAsset
338	    ? join(app.getPath("userData"), "assets")
339	    : app.isPackaged
340	      ? join(app.getAppPath(), "dist")
341	      : resolve(mainDirectory, "../dist");
342	  const relativeRequestPath = isLibraryAsset
343	    ? `/${requestPath.slice(libraryAssetPrefix.length)}`
344	    : requestPath;
345	  return serveAssetFile(request, {
346	    root: assetDirectory,
347	    path: relativeRequestPath,
348	    contentTypes: mimeTypes,
349	    headers: { "Content-Security-Policy": contentSecurityPolicy },
350	  });
351	}
