353	function createWindow() {
354	  mainWindow = new BrowserWindow({
355	    title: "inkling",
356	    width: 1280,
357	    height: 720,
358	    // 320px matches the body min-width in src/index.css. At 240px high the library grid shrinks to 65px; 360px keeps it near 185px.
359	    minWidth: 320,
360	    minHeight: 360,
361	    frame: false,
362	    titleBarStyle: "hidden",
363	    titleBarOverlay: { color: "#00000000", symbolColor: "#e5ddd2", height: 32 },
364	    autoHideMenuBar: true,
365	    backgroundColor: "#0c0c0b",
366	    show: false,
367	    webPreferences: {
368	      preload: join(mainDirectory, "preload.cjs"),
369	      contextIsolation: true,
370	      nodeIntegration: false,
371	      sandbox: true,
372	      webSecurity: true,
373	      // HTML-in-Canvas, so liquid glass can refract the live grid. Chromium
374	      // ships it behind this flag; without it the renderer keeps the CSS glass.
375	      enableBlinkFeatures: "CanvasDrawElement",
376	    },
377	  });
378	  mainWindow.setMenu(null);
379	  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
380	    const externalUrl = parseHttpUrlCore(url)?.toString();
381	    if (externalUrl) void shell.openExternal(externalUrl).catch(() => {});
382	    return { action: "deny" };
383	  });
384	  mainWindow.webContents.on("will-navigate", (event, target) => {
385	    let url;
386	    try {
387	      url = new URL(target);
388	    } catch {
389	      event.preventDefault();
390	      return;
391	    }
392	    if (url.protocol !== "app:" || url.hostname !== "local") event.preventDefault();
393	  });
394	  // The renderer calls inkling:window:ready once it knows whether the welcome
395	  // runs and has painted that first frame, so a first launch never flashes the
396	  // library before onboarding. The timer only guards against a renderer that
397	  // never says so: the window must always appear.
398	  mainWindow.once("ready-to-show", () => {
399	    const window = mainWindow;
400	    setTimeout(() => {
401	      if (window && !window.isDestroyed() && !window.isVisible()) window.show();
402	    }, 3000);
403	  });
404	  mainWindow.on("closed", () => {
405	    mainWindow = undefined;
406	  });
407	
408	  const query = isPreview ? "?preview=1" : "";
409	  void mainWindow.loadURL(`app://local/index.html${query}`);
410	}
411	
412	const hasSingleInstanceLock = app.requestSingleInstanceLock();
413	if (!hasSingleInstanceLock) {
414	  app.quit();
415	} else {
416	  app.on("second-instance", (_event, argv) => {
417	    handleDeepLinkArguments(argv);
418	    if (mainWindow) {
419	      if (mainWindow.isMinimized()) mainWindow.restore();
420	      mainWindow.focus();
421	    }
422	  });
423	  app.on("open-url", (event, url) => {
424	    event.preventDefault();
425	    enqueueDeepLink(url);
426	  });
427	
428	  void app.whenReady().then(async () => {
429	    if (app.isPackaged) app.setAsDefaultProtocolClient("inkling");
430	    else {
431	      app.setAsDefaultProtocolClient("inkling", process.execPath, [
432	        resolve(process.argv[1] ?? "."),
433	      ]);
434	    }
435	    registerLibraryCommands();
436	    try {
437	      captureServer = await startCaptureServer({
438	        libraryDirectory,
439	        captureUrl: (input) => {
440	          if (!libraryStorage) initializeLibraryStorage();
441	          return requireLibraryStorage().captureUrl(input);
442	        },
443	      });
444	    } catch (error) {
445	      console.error(
446	        `capture server unavailable: ${error instanceof Error ? error.message : String(error)}`,
447	      );
448	    }
449	    await protocol.handle("app", serveAppAsset);
450	    allowCanvasReadableImages();
451	    handleDeepLinkArguments(process.argv);
452	    createWindow();
453	
454	    app.on("activate", () => {
455	      if (BrowserWindow.getAllWindows().length === 0) createWindow();
456	    });
457	    app.on("window-all-closed", () => {
458	      if (process.platform !== "darwin") app.quit();
459	    });
460	    let quitDrainStarted = false;
461	    let quitDrainComplete = false;
462	    app.on("before-quit", (event) => {
463	      if (quitDrainComplete) return;
464	      event.preventDefault();
465	      if (quitDrainStarted) return;
466	      quitDrainStarted = true;
467	      jobWorker?.stop();
468	      thumbnailWorker?.stop();
469	      void (async () => {
470	        try {
471	          await captureServer?.close();
472	        } catch (error) {
473	          console.error(
474	            `capture server shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
475	          );
476	        }
477	        try {
478	          await aiJobProcessors?.close();
479	        } catch (error) {
480	          console.error(
481	            `background jobs shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
482	          );
483	        }
484	        try {
485	          libraryStorage?.db.close();
486	        } catch (error) {
487	          console.error(
488	            `library shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
489	          );
490	        }
491	        quitDrainComplete = true;
492	        app.quit();
493	      })();
494	    });
495	  });
496	}
