182	function summarizeProcessingJobs(jobs: ProcessingJob[]): ProcessingSummary {
183	  const latestJobs = latestJobsByKind(jobs);
184	  const failedJob = latestJobs.find((job) => job.status === "failed") ?? null;
185	  const activeJobs = latestJobs.filter(
186	    (job) => job.status === "pending" || job.status === "processing",
187	  );
188	  const completed = latestJobs.filter((job) => job.status === "completed").length;
189	  const progressTotal = latestJobs.reduce<number | null>((total, job) => {
190	    if (job.progressTotal == null) return total;
191	    return (total ?? 0) + job.progressTotal;
192	  }, null);
193	  const progressCurrent = latestJobs.reduce((current, job) => current + job.progressCurrent, 0);
194	
195	  return {
196	    active: activeJobs.length > 0,
197	    hasOcrJob: latestJobs.some((job) => job.kind === "ocr_image" || job.kind === "ocr_pdf_page"),
198	    completed,
199	    total: latestJobs.length,
200	    progressCurrent,
201	    progressTotal,
202	    message: activeJobs.find((job) => job.progressMessage)?.progressMessage ?? null,
203	    failedJob,
204	  };
205	}
