import { createCanvas, DOMMatrix, ImageData, Path2D } from "@napi-rs/canvas";

const maxCanvasEdge = 8192;
const maxCanvasPixels = 16_777_216;
const maxThumbnailEdge = 512;
const minTextLayerCharacters = 500;
let pdfjsPromise;

async function pdfjs() {
  globalThis.DOMMatrix ??= DOMMatrix;
  globalThis.ImageData ??= ImageData;
  globalThis.Path2D ??= Path2D;
  pdfjsPromise ??= import("pdfjs-dist/legacy/build/pdf.mjs");
  return pdfjsPromise;
}

function normalizeText(value) {
  return value.split(/\s+/).filter(Boolean).join(" ");
}

async function renderPage(page, canvasModule) {
  const naturalViewport = page.getViewport({ scale: 1 });
  const scale = Math.min(
    2,
    maxCanvasEdge / naturalViewport.width,
    maxCanvasEdge / naturalViewport.height,
    Math.sqrt(maxCanvasPixels / (naturalViewport.width * naturalViewport.height)),
  );
  const viewport = page.getViewport({ scale });
  const canvas = canvasModule.createCanvas(Math.ceil(viewport.width), Math.ceil(viewport.height));
  await page.render({ canvasContext: canvas.getContext("2d"), viewport }).promise;
  return canvas.toBuffer("image/png");
}

async function openDocument(bytes) {
  if (!bytes?.length) throw new Error("PDF bytes cannot be empty");
  const library = await pdfjs();
  const loadingTask = library.getDocument({
    data: new Uint8Array(bytes),
    isEvalSupported: false,
    useSystemFonts: true,
  });
  return { library, loadingTask };
}

const isPositiveFinite = (value) => Number.isFinite(value) && value > 0;

async function renderFirstPageThumbnail(page) {
  const natural = page.getViewport({ scale: 1 });
  if (!isPositiveFinite(natural.width) || !isPositiveFinite(natural.height))
    throw new Error("PDF page size is not a finite positive number");
  const viewport = page.getViewport({
    scale: maxThumbnailEdge / Math.max(natural.width, natural.height),
  });
  if (!isPositiveFinite(viewport.width) || !isPositiveFinite(viewport.height))
    throw new Error("PDF thumbnail size is not a finite positive number");
  const edge = (value) => Math.min(maxThumbnailEdge, Math.max(1, Math.round(value)));
  const canvas = createCanvas(edge(viewport.width), edge(viewport.height));
  const context = canvas.getContext("2d");
  context.fillStyle = "#ffffff";
  context.fillRect(0, 0, canvas.width, canvas.height);
  await page.render({ canvasContext: context, viewport }).promise;
  return canvas.toBuffer("image/png");
}

export async function renderPdfFirstPage(bytes) {
  const { loadingTask } = await openDocument(bytes);
  try {
    const page = await (await loadingTask.promise).getPage(1);
    try {
      return await renderFirstPageThumbnail(page);
    } finally {
      page.cleanup();
    }
  } finally {
    await loadingTask.destroy();
  }
}

export async function extractPdfTextByPages(
  bytes,
  { recognize, onProgress = () => {}, ocrEngineName = "tesseract.js", onFirstPageThumbnail } = {},
) {
  const { library, loadingTask } = await openDocument(bytes);
  const pages = [];
  let ocrPages = 0;

  try {
    const document = await loadingTask.promise;
    const imageOperations = new Set(
      [
        library.OPS.paintImageXObject,
        library.OPS.paintInlineImageXObject,
        library.OPS.paintJpegXObject,
        library.OPS.paintImageMaskXObject,
        library.OPS.paintImageMaskXObjectGroup,
        library.OPS.paintImageGroup,
      ].filter((operation) => typeof operation === "number"),
    );
    for (let pageNumber = 1; pageNumber <= document.numPages; pageNumber += 1) {
      const page = await document.getPage(pageNumber);
      if (pageNumber === 1 && onFirstPageThumbnail) {
        try {
          await onFirstPageThumbnail(await renderFirstPageThumbnail(page));
        } catch {}
      }
      const contents = await page.getTextContent();
      let text = normalizeText(
        contents.items.map((item) => ("str" in item ? item.str : "")).join(" "),
      );
      let hasRasterImage = false;
      if (recognize && text.length < minTextLayerCharacters) {
        const operators = await page.getOperatorList();
        hasRasterImage = operators.fnArray.some((operation) => imageOperations.has(operation));
      }
      if (recognize && (!text || (text.length < minTextLayerCharacters && hasRasterImage))) {
        onProgress(
          pageNumber - 1,
          document.numPages,
          `OCR page ${pageNumber} of ${document.numPages}`,
        );
        const image = await renderPage(page, { createCanvas });
        const ocrText = normalizeText(await recognize(image));
        if (ocrText) {
          text = text ? `${text}\n${ocrText}` : ocrText;
          ocrPages += 1;
        }
      }
      pages.push(text);
      page.cleanup();
      onProgress(pageNumber, document.numPages, text ? "Reading PDF text" : "No text found");
    }
  } finally {
    await loadingTask.destroy();
  }

  return {
    pages,
    text: pages.filter(Boolean).join("\n\n"),
    engine: ocrPages ? `pdf-text+${ocrEngineName}` : "pdf-text",
    ocrPages,
  };
}
import sharp from "sharp";

const maxImageDimension = 20_000;
const maxImageAllocation = 256 * 1024 * 1024;
const maxImagePixels = Math.floor(maxImageAllocation / 8);
const thumbnailEdge = 512;

export function validateImageDimensions(width, height) {
  if (!width || !height) throw new Error("image processing error: unable to decode image");
  if (
    width > maxImageDimension ||
    height > maxImageDimension ||
    width * height * 8 > maxImageAllocation
  ) {
    throw new Error("image processing error: image dimensions exceed safe limits");
  }
}

function validateIconImage(bytes) {
  const count = bytes.readUInt16LE(4);
  const directoryEnd = 6 + count * 16;
  if (count < 1 || directoryEnd > bytes.length) {
    throw new Error("invalid ICO image directory");
  }

  for (let index = 0; index < count; index += 1) {
    const entry = 6 + index * 16;
    validateImageDimensions(bytes[entry] || 256, bytes[entry + 1] || 256);
    const size = bytes.readUInt32LE(entry + 8);
    const offset = bytes.readUInt32LE(entry + 12);
    if (offset < directoryEnd || offset + size > bytes.length || size < 12) {
      throw new Error("invalid ICO image data");
    }

    const image = bytes.subarray(offset, offset + size);
    const isPng = image.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]));
    if (isPng) {
      if (image.length < 24) throw new Error("invalid ICO PNG data");
      validateImageDimensions(image.readUInt32BE(16), image.readUInt32BE(20));
      continue;
    }

    const headerSize = image.readUInt32LE(0);
    if (headerSize >= 40 && headerSize <= size) {
      validateImageDimensions(Math.abs(image.readInt32LE(4)), Math.abs(image.readInt32LE(8)));
      continue;
    }
    if (headerSize === 12) {
      validateImageDimensions(image.readUInt16LE(4), image.readUInt16LE(6));
      continue;
    }
    throw new Error("unsupported ICO image data");
  }
}

// BMP and ICO are not sharp formats, so they get header checks here and a
// canvas decode later. Returns false for anything else.
function validateLegacyImageHeader(bytes) {
  const isBitmap = bytes.subarray(0, 2).toString("ascii") === "BM";
  const isIcon = bytes.length >= 6 && bytes.readUInt16LE(0) === 0 && bytes.readUInt16LE(2) === 1;
  if (!isBitmap && !isIcon) return false;
  if (isIcon) validateIconImage(bytes);
  if (isBitmap && bytes.length >= 26) {
    const coreHeader = bytes.readUInt32LE(14) === 12;
    const width = coreHeader ? bytes.readUInt16LE(18) : bytes.readInt32LE(18);
    const height = coreHeader ? bytes.readUInt16LE(20) : bytes.readInt32LE(22);
    validateImageDimensions(Math.abs(width), Math.abs(height));
  }
  return true;
}

function orientedSize({ width, height, orientation }) {
  const isRotated = orientation != null && orientation >= 5 && orientation <= 8;
  return isRotated ? { width: height, height: width } : { width, height };
}

// Capture's gate. It reads the header only, so even a 50 MB original costs
// milliseconds; resizing is left to the background thumbnail job. BMP and ICO
// have no cheap size read, so they return null and gain their size with the
// thumbnail.
export async function inspectImage(bytes) {
  let metadata;
  try {
    metadata = await sharp(bytes, { limitInputPixels: maxImagePixels }).metadata();
  } catch (error) {
    if (!validateLegacyImageHeader(bytes)) throw error;
    return null;
  }
  validateImageDimensions(metadata.width, metadata.height);
  return orientedSize(metadata);
}

export async function sharpImageInput(bytes) {
  try {
    await sharp(bytes, { limitInputPixels: maxImagePixels }).metadata();
    return bytes;
  } catch (error) {
    if (!validateLegacyImageHeader(bytes)) throw error;
    const [{ CanvasElement }, { default: loadImage }] = await Promise.all([
      import("@napi-rs/canvas/js-binding.js"),
      import("@napi-rs/canvas/load-image.js"),
    ]);
    const image = await loadImage(bytes);
    validateImageDimensions(image.width, image.height);
    const canvas = new CanvasElement(image.width, image.height);
    canvas.getContext("2d").drawImage(image, 0, 0);
    return canvas.encode("png");
  }
}

export async function createImageThumbnail(bytes) {
  const input = await sharpImageInput(bytes);
  const image = sharp(input, { limitInputPixels: maxImagePixels });
  const metadata = await image.metadata();
  validateImageDimensions(metadata.width, metadata.height);
  const thumbnail = await image
    .rotate()
    .resize({
      width: thumbnailEdge,
      height: thumbnailEdge,
      fit: "inside",
      withoutEnlargement: true,
    })
    .webp()
    .toBuffer();
  return { bytes: thumbnail, ...orientedSize(metadata) };
}

export async function dominantImageColors(bytes) {
  const input = await sharpImageInput(bytes);
  const { data, info } = await sharp(input, { limitInputPixels: maxImagePixels })
    .resize({ width: 64, height: 64, fit: "inside", withoutEnlargement: true })
    .removeAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  const bins = new Map();
  for (let index = 0; index < data.length; index += info.channels) {
    const red = data[index] >> 4;
    const green = data[index + 1] >> 4;
    const blue = data[index + 2] >> 4;
    const key = (red << 8) | (green << 4) | blue;
    bins.set(key, (bins.get(key) ?? 0) + 1);
  }
  const colors = [...bins]
    .sort((left, right) => right[1] - left[1])
    .slice(0, 5)
    .map(
      ([key]) =>
        `#${((key >> 8) * 17).toString(16).padStart(2, "0")}${(((key >> 4) & 15) * 17).toString(16).padStart(2, "0")}${((key & 15) * 17).toString(16).padStart(2, "0")}`,
    );
  while (colors.length < 5) colors.push(colors.at(-1) ?? "#000000");
  return colors;
}
const posterEdge = 512;

// The OS shell decodes the frame, so inkling ships no codec or ffmpeg. The shell
// thumbnailer only exists on Windows and macOS; elsewhere, and for any file the
// shell cannot read, there is no poster and the card keeps the typed video artwork.
export async function createVideoPoster(filePath, { nativeImage } = {}) {
  const thumbnailer = nativeImage ?? (await import("electron")).nativeImage;
  if (typeof thumbnailer?.createThumbnailFromPath !== "function") return null;
  const image = await thumbnailer.createThumbnailFromPath(filePath, {
    width: posterEdge,
    height: posterEdge,
  });
  return image.isEmpty() ? null : image.toPNG();
}

