    const chunks = [];
    let length = 0;
    let tooLarge = false;
    for await (const chunk of request) {
      length += chunk.length;
      if (length > MAX_JSON_BYTES) {
        tooLarge = true;
        chunks.length = 0;
      } else if (!tooLarge) {
        chunks.push(chunk);
      }
