  const seen = new Set();
  const cleaned = [];
  for (const entry of values) {
    const trimmed = entry.trim();
    if (!trimmed || seen.has(trimmed)) continue;
    seen.add(trimmed);
    let parsed;
    try {
      parsed = new URL(trimmed);
    } catch {
