    !Number.isInteger(request.version) ||
    request.version < 0 ||
    request.version > 255 ||
    !hasStringField(request, "kind") ||
    !hasStringField(request, "url") ||
    !hasStringField(request, "title", true) ||
    !hasStringField(request, "defuddledHtml", true) ||
    !hasStringField(request, "text", true) ||
