type IngestionExtractor = "defuddle" | "fallback";

export type SafeEmbedKind = "iframe" | "video" | "audio";

export type SafeEmbedProvider =
  | "direct"
  | "loom"
  | "soundcloud"
  | "spotify"
  | "twitch"
  | "vimeo"
  | "youtube";

export interface SafeEmbedCandidate {
  kind: SafeEmbedKind;
  provider: SafeEmbedProvider;
  sourceUrl: string;
  embedUrl: string;
  title?: string;
}

export interface ImageDimensions {
  url: string;
  width: number;
  height: number;
}

export interface XPostMetadata {
  provider: "x";
  postUrl: string;
  postId: string;
  embedHtml?: string;
  authorName?: string;
  authorUrl?: string;
  authorHandle?: string;
  text?: string;
  publishedDate?: string | null;
  width?: number | null;
}

export interface NormalizedArticle {
  sourceUrl: string;
  fetchedUrl: string;
  canonicalUrl: string;
  title: string;
  description: string;
  author: string;
  publishedDate: string | null;
  html: string;
  text: string;
  imageUrls: string[];
  imageDimensions: ImageDimensions[];
  safeEmbeds: SafeEmbedCandidate[];
  extractor: IngestionExtractor;
  social?: XPostMetadata;
}

export interface RawArticleExtraction {
  title?: string;
  description?: string;
  author?: string;
  publishedDate?: string | null;
  canonicalUrl?: string;
  contentHtml?: string;
  imageUrls?: string[];
  imageDimensions?: ImageDimensions[];
}

export interface DefuddleAdapter {
  readonly name: string;
  extract(document: Document, url: string): RawArticleExtraction | Promise<RawArticleExtraction>;
}

export interface UrlIngestionOptions {
  fetch?: typeof globalThis.fetch;
  timeoutMs?: number;
  maxResponseBytes?: number;
  userAgent?: string;
  defuddleAdapter?: DefuddleAdapter;
  /** Only enable this for trusted local fixture servers, never for user input. */
  allowPrivateNetwork?: boolean;
}
export type UrlIngestionErrorCode =
  | "content-too-large"
  | "extraction-failed"
  | "invalid-url"
  | "network-error"
  | "parse-failed"
  | "unsupported-content-type"
  | "http-error"
  | "redirect-error"
  | "timeout";

export interface UrlIngestionErrorDetails {
  cause?: unknown;
  status?: number;
  url?: string;
}

export class UrlIngestionError extends Error {
  readonly name = "UrlIngestionError";

  constructor(
    readonly code: UrlIngestionErrorCode,
    message: string,
    readonly details: UrlIngestionErrorDetails = {},
  ) {
    super(message);
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export function isUrlIngestionError(error: unknown): error is UrlIngestionError {
  return error instanceof UrlIngestionError;
}

