import { mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { enrichmentMethods } from "./storage/enrichment.mjs";
import { exportMethods } from "./storage/export-library.mjs";
import { importMethods } from "./storage/import-library.mjs";
import { itemMethods } from "./storage/items.mjs";
import { JobQueue } from "./storage/jobs.mjs";
import { openDatabase, SCHEMA_VERSION } from "./storage/schema.mjs";
import { searchMethods } from "./storage/search.mjs";
import { spaceMethods } from "./storage/spaces.mjs";

export {
  IMAGE_PALETTE_JOB,
  IMAGE_THUMBNAIL_JOB,
  JOB_LEASE_MILLIS,
  JobQueue,
  JobWorker,
  PDF_THUMBNAIL_JOB,
  URL_ENRICHMENT_JOB,
  VIDEO_POSTER_JOB,
} from "./storage/jobs.mjs";
export { markdownToPlainText } from "./storage/shared.mjs";

export function resolveLibraryDataDirectory({
  executablePath,
  appDataDirectory,
  identifier = "com.inkling.library",
  portable = false,
  overrideDirectory,
}) {
  if (portable) return join(dirname(executablePath), "data");
  if (overrideDirectory) return resolve(overrideDirectory);
  return join(appDataDirectory, identifier);
}

export function openLibraryStorage(databasePath, options = {}) {
  const database = resolve(databasePath);
  mkdirSync(dirname(database), { recursive: true });
  const { db, fts5Enabled } = openDatabase(database);
  db.function("inkling_unicode_lower", { deterministic: true }, (value) =>
    String(value ?? "").toLowerCase(),
  );
  const jobQueue = new JobQueue(db, options.jobQueue);
  const library = new LibraryStorage(database, db, fts5Enabled, jobQueue, options);
  return library;
}

class LibraryStorage {
  constructor(
    databasePath,
    db,
    fts5Enabled,
    jobs,
    { createThumbnail, inspectImage, createSnapshot } = {},
  ) {
    this.databasePath = databasePath;
    this.assetsRoot = join(dirname(databasePath), "assets");
    this.assetsDirectory = join(this.assetsRoot, "items");
    this.db = db;
    this.fts5Enabled = fts5Enabled;
    this.jobs = jobs;
    this.createThumbnail = createThumbnail;
    this.inspectImage = inspectImage;
    this.createSnapshot = createSnapshot;
  }

  status() {
    return {
      databasePath: this.databasePath,
      fts5Enabled: this.fts5Enabled,
      schemaVersion: SCHEMA_VERSION,
    };
  }

  // Rows written through this connection since it opened. The main process is
  // the only writer, so an unchanged count means the library has not changed.
  changeCount() {
    return this.db.prepare("SELECT total_changes() AS changes").get().changes;
  }

  hasCompletedOnboarding() {
    return (
      this.db.prepare("SELECT 1 FROM app_settings WHERE key = 'onboarding_completed'").get() !==
      undefined
    );
  }

  completeOnboarding() {
    this.db
      .prepare(
        "INSERT OR REPLACE INTO app_settings (key, value) VALUES ('onboarding_completed', '1')",
      )
      .run();
  }
}

Object.assign(
  LibraryStorage.prototype,
  itemMethods,
  enrichmentMethods,
  searchMethods,
  spaceMethods,
  exportMethods,
  importMethods,
);
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";
import { isAbsolute, relative, sep } from "node:path";

export const itemColumns = `id, kind, title, description, source_url, source_label,
  local_asset_path, thumbnail_path, ocr_text, metadata, created_at, updated_at,
  archived, NULL AS body, 'md' AS body_format`;
export const qualifiedItemColumns = `i.id, i.kind, i.title, i.description, i.source_url, i.source_label,
  i.local_asset_path, i.thumbnail_path, i.ocr_text, i.metadata, i.created_at, i.updated_at,
  i.archived, NULL AS body, 'md' AS body_format`;
const cardMetadataFields = [
  "tags",
  "social",
  "imageUrls",
  "imageDimensions",
  "mediaWidth",
  "mediaHeight",
  "mediaAspectRatio",
  "pdfPageCount",
];

export function nowMillis() {
  return Date.now();
}

export function parseJson(value, fallback) {
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

export function parseObject(value, label = "metadata") {
  if (value == null) return {};
  if (typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${label} must be a JSON object`);
  }
  return value;
}

export function itemFromRow(row) {
  if (!row) return null;
  const metadata = parseJson(row.metadata, {});
  return {
    id: row.id,
    kind: row.kind,
    title: row.title,
    description: row.description,
    body: row.body,
    bodyFormat: row.body_format,
    sourceUrl: row.source_url,
    sourceLabel: row.source_label,
    localAssetPath: row.local_asset_path,
    thumbnailPath: row.thumbnail_path,
    ocrText: row.ocr_text,
    metadata,
    palette: Array.isArray(metadata.palette) ? metadata.palette : undefined,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    archived: row.archived !== 0,
  };
}

export function cardItem(item) {
  const metadata =
    item.metadata && typeof item.metadata === "object" && !Array.isArray(item.metadata)
      ? item.metadata
      : {};
  const cardMetadata = {};
  for (const field of cardMetadataFields) {
    if (Object.hasOwn(metadata, field)) cardMetadata[field] = metadata[field];
  }
  return {
    id: item.id,
    kind: item.kind,
    title: item.title,
    description: item.description,
    sourceUrl: item.sourceUrl,
    sourceLabel: item.sourceLabel,
    localAssetPath: item.localAssetPath,
    thumbnailPath: item.thumbnailPath,
    palette: Array.isArray(metadata.palette) ? metadata.palette : undefined,
    ocrText: String(item.ocrText ?? "")
      .trim()
      .slice(0, 180),
    metadata: cardMetadata,
    createdAt: item.createdAt,
    archived: item.archived,
    hasArticleContent: typeof metadata.html === "string" && Boolean(metadata.html.trim()),
  };
}

export function nonEmpty(value) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

export function normalizeHttpUrl(value) {
  let url;
  try {
    url = new URL(value.trim());
  } catch {
    throw new Error("invalid storage input: sourceUrl must be a valid HTTP or HTTPS URL");
  }
  if (!(url.protocol === "http:" || url.protocol === "https:") || !url.hostname) {
    throw new Error("invalid storage input: sourceUrl must use HTTP or HTTPS and include a host");
  }
  url.hash = "";
  return url.toString();
}

export function markdownToPlainText(markdown) {
  return markdown
    .replace(/```[^\n]*\n([\s\S]*?)```/g, "$1")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/<br\s*\/?>|<hr\s*\/?>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/^\s{0,3}(?:#{1,6}\s+|>\s?|[-+*]\s+|\d+\.\s+)/gm, " ")
    .replace(/[*_~]/g, "")
    .split(/\s+/)
    .filter(Boolean)
    .join(" ")
    .replace(/ \./g, ".")
    .replace(/ ,/g, ",")
    .replace(/ ;/g, ";")
    .replace(/ :/g, ":")
    .replace(/ !/g, "!")
    .replace(/ \?/g, "?");
}

export function validateItemId(id) {
  const value = String(id ?? "").trim();
  if (value.length < 1 || value.length > 128) {
    throw new Error("invalid storage input: item id must contain 1 to 128 characters");
  }
  if (!/^[a-zA-Z0-9_-]+$/.test(value)) {
    throw new Error("invalid storage input: item id contains unsupported characters");
  }
  return value;
}

export function clampLimit(value, fallback, maximum) {
  const limit = Number(value);
  return Number.isFinite(limit) ? Math.min(maximum, Math.max(1, Math.trunc(limit))) : fallback;
}

export function itemSelect(
  db,
  where,
  params = [],
  order = "updated_at DESC, created_at DESC",
  limit,
) {
  const limitClause = limit == null ? "" : " LIMIT ?";
  return db
    .prepare(`SELECT ${itemColumns} FROM items WHERE ${where} ORDER BY ${order}${limitClause}`)
    .all(...params, ...(limit == null ? [] : [limit]))
    .map(itemFromRow)
    .map(cardItem);
}

export function isInside(candidate, root) {
  const pathFromRoot = relative(root, candidate);
  return (
    pathFromRoot === "" ||
    (!pathFromRoot.startsWith(`..${sep}`) && pathFromRoot !== ".." && !isAbsolute(pathFromRoot))
  );
}

export async function sha256File(path) {
  const hash = createHash("sha256");
  for await (const chunk of createReadStream(path)) hash.update(chunk);
  return hash.digest("hex");
}
import { DatabaseSync } from "node:sqlite";

export const SCHEMA_VERSION = 8;

const itemsSchema = `
CREATE TABLE IF NOT EXISTS items (
  id TEXT PRIMARY KEY NOT NULL,
  kind TEXT NOT NULL,
  title TEXT,
  description TEXT,
  body TEXT NOT NULL DEFAULT '',
  body_format TEXT NOT NULL DEFAULT 'md',
  source_url TEXT,
  source_label TEXT,
  local_asset_path TEXT,
  thumbnail_path TEXT,
  ocr_text TEXT NOT NULL DEFAULT '',
  metadata TEXT NOT NULL DEFAULT '{}',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
  -- Pins have no UI for now. The column stays, and restore copies it, so pins
  -- saved before they were removed are still there if they come back.
  favorite INTEGER NOT NULL DEFAULT 0 CHECK (favorite IN (0, 1))
);
CREATE INDEX IF NOT EXISTS idx_items_active_updated ON items (archived, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_items_kind ON items (kind);
`;

const jobsSchema = `
CREATE TABLE IF NOT EXISTS jobs (
  id TEXT PRIMARY KEY NOT NULL,
  item_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  retry_count INTEGER NOT NULL DEFAULT 0,
  max_retries INTEGER NOT NULL DEFAULT 3,
  error_message TEXT,
  created_at INTEGER NOT NULL,
  started_at INTEGER,
  completed_at INTEGER,
  worker_id TEXT,
  lease_until INTEGER,
  progress_current INTEGER NOT NULL DEFAULT 0,
  progress_total INTEGER,
  progress_message TEXT
);
CREATE INDEX IF NOT EXISTS idx_jobs_status_created ON jobs (status, created_at);
CREATE INDEX IF NOT EXISTS idx_jobs_item ON jobs (item_id, created_at DESC);
`;

const embeddingsSchema = `
CREATE TABLE IF NOT EXISTS item_embeddings (
  item_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('text', 'image')),
  model TEXT NOT NULL,
  dimension INTEGER NOT NULL CHECK (dimension > 0),
  vector BLOB NOT NULL,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (item_id, kind)
);
CREATE INDEX IF NOT EXISTS idx_item_embeddings_kind ON item_embeddings (kind, model);
`;

const spacesSchema = `
CREATE TABLE IF NOT EXISTS spaces (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL,
  color TEXT NOT NULL DEFAULT 'blue',
  query TEXT NOT NULL DEFAULT '{}',
  kind TEXT NOT NULL DEFAULT 'smart',
  position INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
