33	function createWorker(
34	  library: ReturnType<typeof openLibraryStorage>,
35	  options: ConstructorParameters<typeof JobWorker>[1],
36	) {
37	  const worker = new JobWorker(library, options);
38	  workers.add(worker);
39	  return worker;
40	}
41	
42	async function stopWorker(worker: JobWorker) {
43	  workers.delete(worker);
44	  await worker.stop();
45	}
46	
47	function trackDatabase(database: DatabaseSync) {
48	  databases.add(database);
49	  return database;
50	}
51	
52	function closeDatabase(database: DatabaseSync) {
53	  databases.delete(database);
54	  database.close();
55	}
