57	test("completed onboarding persists across library reopen", () => {
58	  const { root, library } = temporaryLibrary();
59	  expect(library.hasCompletedOnboarding()).toBe(false);
60	  library.completeOnboarding();
61	  closeDatabase(library.db);
62	  expect(trackedLibrary(join(root, "library.sqlite3")).hasCompletedOnboarding()).toBe(true);
63	});
64	
65	function trackedLibrary(path: string, options = {}) {
66	  const library = openLibraryStorage(path, options);
67	  databases.add(library.db);
68	  return library;
69	}
70	
71	function temporaryLibrary(options = {}) {
72	  const root = mkdtempSync(join(tmpdir(), "inkling-electron-storage-"));
73	  roots.push(root);
74	  return { root, library: trackedLibrary(join(root, "library.sqlite3"), options) };
75	}
