77	function enrichUrl(
78	  library: ReturnType<typeof openLibraryStorage>,
79	  itemId: string,
80	  article: object,
81	) {
82	  const workerId = `url-test-${randomUUID()}`;
83	  const job = library.jobs.claimNext(workerId);
84	  if (!job) throw new Error("URL enrichment job was not available");
85	  expect(job).toMatchObject({ itemId, kind: URL_ENRICHMENT_JOB, status: "processing" });
86	  expect(library.applyUrlEnrichment(job.id, workerId, article)).toBe(true);
87	  expect(library.jobs.complete(job.id, workerId)).toBe(true);
88	}
