90	function seedFromDemo(library: ReturnType<typeof openLibraryStorage>) {
91	  const selected = personalSeedItems.filter((item) => parity.sourceIds.includes(item.id));
92	  const insert =
93	    library.db.prepare(`INSERT INTO items (id, kind, title, description, body, body_format,
94	    source_label, metadata, ocr_text, created_at, updated_at)
95	    VALUES (?, ?, ?, ?, '', 'md', 'Downloads', ?, '', ?, ?)`);
96	  selected.forEach((item, index) => {
97	    const id = item.id;
98	    const now = index + 1;
99	    insert.run(
100	      id,
101	      item.kind.toLowerCase(),
102	      item.title,
103	      item.description,
104	      JSON.stringify({ tags: item.tags }),
105	      now,
106	      now,
107	    );
108	  });
109	  return selected;
110	}
