]);
const silentKindsSql = [...SILENT_JOB_KINDS].map((kind) => `'${kind}'`).join(", ");

type JobRow = {
  id: string;
  item_id: string;
  kind: string;
  status: string;
  retry_count: number;
  max_retries: number;
  error_message: string | null;
  created_at: number;
  started_at: number | null;
  completed_at: number | null;
  progress_current: number;
  progress_total: number | null;
  progress_message: string | null;
};

type JobOwner = { item_id: string; kind: string };

export type Job = ProcessingJob;

function jobFromRow(row: JobRow): Job {
  return {
    id: row.id,
    itemId: row.item_id,
    kind: row.kind as Job["kind"],
    status: row.status as Job["status"],
    retryCount: row.retry_count,
    maxRetries: row.max_retries,
    errorMessage: row.error_message,
    createdAt: row.created_at,
    startedAt: row.started_at,
    completedAt: row.completed_at,
    progressCurrent: row.progress_current,
    progressTotal: row.progress_total,
    progressMessage: row.progress_message,
  };
}

const changes = (result: unknown) => (result as { changes: number }).changes;

