          source_label, metadata, ocr_text, created_at, updated_at)
          VALUES (${id}, 'url', ${input.title}, NULL, '', '', ${sourceUrl}, ${sourceLabel},
          ${JSON.stringify(metadata)}, '', ${now}, ${now})`;
