      Effect.map((rows) => rows.map((row) => row.id)),
    );

  return {
    listSpaces,
    getSpace,
    createSpace,
    updateSpace,
    deleteSpace,
    swapSpacePositions,
    listSpaceItems,
    addSpaceItem,
    removeSpaceItem,
    listItemSpaces,
