import { Effect } from "effect";
import type { SqlClient } from "effect/sql/SqlClient";
import type { Fragment } from "effect/sql/Statement";
import type { JobQueue } from "./jobs.ts";
import { cardFromRow, detailColumns, type ItemRow, itemColumns, itemFromRow } from "./shared.ts";

export type Thumbnail = { bytes: Uint8Array; width?: number | null; height?: number | null };

export type StorageMedia = {
  createThumbnail?: (bytes: Buffer) => Promise<Thumbnail>;
  inspectImage?: (bytes: Buffer) => Promise<{ width: number; height: number } | null | undefined>;
  createSnapshot?: (source: string, destination: string) => Promise<void>;
};

export type StorageContext = {
  sql: SqlClient;
  jobs: JobQueue["Service"];
  databasePath: string;
  assetsRoot: string;
  assetsDirectory: string;
  fts5Enabled: boolean;
  media: StorageMedia;
};

export const selectCards = (
  { sql }: StorageContext,
  where: Fragment,
  limit: number | null = null,
) =>
  sql<ItemRow>`SELECT ${sql.literal(itemColumns)} FROM items WHERE ${where}
    ORDER BY updated_at DESC, created_at DESC ${limit == null ? sql.literal("") : sql`LIMIT ${limit}`}`.pipe(
    Effect.map((rows) => rows.map(cardFromRow)),
  );

export const readItem = ({ sql }: StorageContext, id: string) =>
  sql<ItemRow>`SELECT ${sql.literal(detailColumns)} FROM items WHERE id = ${id}`.pipe(
    Effect.map(([row]) => (row ? itemFromRow(row) : null)),
  );
import { Effect, Schema } from "effect";
import { SqlError } from "effect/sql/SqlError";

// The renderer shows these messages, so each keeps the wording it had before storage moved to Effect.
export class StorageError extends Schema.TaggedError<StorageError>()("StorageError", {
  message: Schema.String,
}) {}

export const invalidInput = (detail: string) =>
  new StorageError({ message: `invalid storage input: ${detail}` });

export const itemNotFound = (id: unknown) =>
  new StorageError({ message: `item not found: ${String(id)}` });

export const spaceNotFound = (id: unknown) =>
  new StorageError({ message: `space not found: ${String(id)}` });

export const storageFailure = (message: string) => new StorageError({ message });

// Wraps a promise from node:fs, sharp, or a model so its rejection stays a typed failure.
export const attempt = <A>(evaluate: (signal: AbortSignal) => PromiseLike<A>) =>
  Effect.tryPromise({ try: evaluate, catch: (cause) => cause });

// SqlError's own message is a generic summary; the SQLite message is on its cause.
export function errorMessage(error: unknown): string {
  if (error instanceof SqlError) {
    const cause = error.reason.cause;
    return cause instanceof Error ? cause.message : error.message;
  }
  return error instanceof Error ? error.message : String(error);
}

export function toError(error: unknown) {
  if (error instanceof StorageError || !(error instanceof SqlError)) return error;
  return new Error(errorMessage(error), { cause: error });
}
import { randomUUID } from "node:crypto";
import { mkdir, realpath, rename, rm, writeFile } from "node:fs/promises";
import { extname, join, resolve, sep } from "node:path";
import { types } from "node:util";
import { Effect } from "effect";
import type {
  CaptureUrlInput,
  CreateNoteInput,
  CreateQuoteInput,
  UpdateItemInput,
} from "@inkling/contracts";
import { selectCards, readItem, type StorageContext } from "./context.ts";
import { attempt, invalidInput, itemNotFound } from "./errors.ts";
import { IMAGE_THUMBNAIL_JOB, URL_ENRICHMENT_JOB, VIDEO_POSTER_JOB } from "./jobs.ts";
