// manifest's hashes. Returns how many files had no integrity record to check.
async function verifyExportAssets(
  exportRoot: string,
  manifest: Manifest,
  items: ImportedItem[],
  actualPaths: string[],
) {
  const itemIds = new Set(items.map((item) => item.id));
  for (const item of items) {
