          AND kind NOT IN (${sql.literal(silentKindsSql)})
        ) WHERE rank = 1 ORDER BY created_at DESC`.pipe(Effect.map((rows) => rows.map(jobFromRow)));

  const getForItem = (itemId: string) =>
