export function createTesseractOcr({
  cacheDirectory,
  workerFactory = createWorker,
}: {
  cacheDirectory: string;
  workerFactory?: OcrWorkerFactory;
}) {
  const cachePath = resolve(cacheDirectory);
  let workerPromise: Promise<OcrWorker> | null | undefined;

  async function worker(): Promise<OcrWorker> {
    workerPromise ??= (async () => {
      await mkdir(cachePath, { recursive: true });
  ) => Promise<{ isEmpty(): boolean; toPNG(): Buffer }>;
};

export async function createVideoPoster(
  filePath: string,
  { nativeImage }: { nativeImage?: Thumbnailer } = {},
) {
  const thumbnailer: Thumbnailer | undefined = nativeImage ?? (await import("electron")).nativeImage;
  if (typeof thumbnailer?.createThumbnailFromPath !== "function") return null;
  const image = await thumbnailer.createThumbnailFromPath(filePath, {
    width: posterEdge,
    height: posterEdge,
  });
  return image.isEmpty() ? null : image.toPNG();
}
