  list_active_items: () => ipcRenderer.invoke("inkling:list_active_items"),
  list_archived_items: () => ipcRenderer.invoke("inkling:list_archived_items"),
  get_item: (args: unknown) => ipcRenderer.invoke("inkling:get_item", args),
  get_item_cards: (args: unknown) => ipcRenderer.invoke("inkling:get_item_cards", args),
  get_change_count: () => ipcRenderer.invoke("inkling:get_change_count"),
  get_item_content: (args: unknown) => ipcRenderer.invoke("inkling:get_item_content", args),
  search_items: (args: unknown) => ipcRenderer.invoke("inkling:search_items", args),
  search_similar_images: (args: unknown) => ipcRenderer.invoke("inkling:search_similar_images", args),
  search_similar_text: (args: unknown) => ipcRenderer.invoke("inkling:search_similar_text", args),
  list_spaces: () => ipcRenderer.invoke("inkling:list_spaces"),
  create_space: (args: unknown) => ipcRenderer.invoke("inkling:create_space", args),
  delete_space: (args: unknown) => ipcRenderer.invoke("inkling:delete_space", args),
  update_space: (args: unknown) => ipcRenderer.invoke("inkling:update_space", args),
  swap_space_positions: (args: unknown) => ipcRenderer.invoke("inkling:swap_space_positions", args),
  list_space_items: (args: unknown) => ipcRenderer.invoke("inkling:list_space_items", args),
  add_space_item: (args: unknown) => ipcRenderer.invoke("inkling:add_space_item", args),
  remove_space_item: (args: unknown) => ipcRenderer.invoke("inkling:remove_space_item", args),
  list_item_spaces: (args: unknown) => ipcRenderer.invoke("inkling:list_item_spaces", args),
  create_note: (args: unknown) => ipcRenderer.invoke("inkling:create_note", args),
  create_quote: (args: unknown) => ipcRenderer.invoke("inkling:create_quote", args),
  capture_url: (args: unknown) => ipcRenderer.invoke("inkling:capture_url", args),
  save_file: (args: unknown) => ipcRenderer.invoke("inkling:save_file", args),
  resolve_asset_path: (args: unknown) => ipcRenderer.invoke("inkling:resolve_asset_path", args),
  update_item: (args: unknown) => ipcRenderer.invoke("inkling:update_item", args),
  archive_item: (args: unknown) => ipcRenderer.invoke("inkling:archive_item", args),
  delete_item: (args: unknown) => ipcRenderer.invoke("inkling:delete_item", args),
  export_library: (args: unknown) => ipcRenderer.invoke("inkling:export_library", args),
  import_library: (args: unknown) => ipcRenderer.invoke("inkling:import_library", args),
