import type { DeepLinkCapture } from "./lib/deepLink";

type ElectronCommand =
  | "check_for_updates"
  | "install_update"
  | "initialize_storage"
  | "get_app_version"
  | "get_library_size"
  | "get_last_export"
  | "show_library_folder"
  | "show_item_in_folder"
  | "list_active_items"
  | "list_archived_items"
  | "get_item"
  | "get_item_cards"
  | "get_change_count"
  | "get_item_content"
  | "search_items"
  | "search_similar_images"
  | "search_similar_text"
  | "list_spaces"
  | "create_space"
  | "delete_space"
  | "update_space"
  | "swap_space_positions"
  | "list_space_items"
  | "add_space_item"
