  | "list_item_spaces"
  | "create_note"
  | "create_quote"
  | "capture_url"
  | "save_file"
  | "resolve_asset_path"
  | "update_item"
  | "archive_item"
  | "delete_item"
  | "export_library"
  | "import_library"
  | "get_jobs_for_items"
  | "count_active_jobs"
  | "get_onboarding_state"
  | "complete_onboarding"
  | "enqueue_ocr_job"
  | "retry_processing_job"
  | "get_capture_status"
  | "get_pairing_token"
  | "regenerate_pairing_token"
  | "select_library_directory"
  | "plugin:deep-link|get_current";

type ElectronBridge = {
  commands: Record<ElectronCommand, (args?: Record<string, unknown>) => Promise<unknown>>;
  onDeepLink: (listener: (captures: DeepLinkCapture[]) => void) => Promise<() => void>;
  onJobUpdated: (listener: (payload: { itemId: string }) => void) => () => void;
  windowControls: {
    minimize: () => Promise<void>;
    toggleMaximize: () => Promise<void>;
    close: () => Promise<void>;
    /** Shows the window, once the first frame worth showing has painted. */
    ready: () => Promise<void>;
  };
};

declare global {
  interface Window {
    inkling?: ElectronBridge;
  }
}

