189	  timeoutMs: number,
190	  maxResponseBytes: number,
191	  userAgent: string,
192	): Promise<NormalizedArticle> {
193	  let title = `${providerLabel(videoLink.provider)} video`;
194	  let author = "";
195	  let poster = videoLink.posterUrl;
196	
197	  if (fetchImpl) {
198	    const controller = new AbortController();
199	    const timeout = setTimeout(() => controller.abort(), Math.min(timeoutMs, 4_000));
200	    try {
201	      const host = videoLink.provider === "youtube" ? "www.youtube.com" : "vimeo.com";
