264	export async function ingestUrl(
265	  input: string,
266	  options: UrlIngestionOptions = {},
267	): Promise<NormalizedArticle> {
268	  const sourceUrl = parseHttpUrl(input, {
269	    allowPrivateNetwork: options.allowPrivateNetwork,
270	  }).toString();
271	  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
272	  const maxResponseBytes = options.maxResponseBytes ?? DEFAULT_MAX_RESPONSE_BYTES;
273	  const fetchImpl = options.fetch ?? globalThis.fetch;
274	
275	  const videoLink = videoLinkFromSourceUrl(sourceUrl);
276	  if (videoLink) {
277	    return ingestVideoLink(
278	      sourceUrl,
279	      videoLink,
280	      fetchImpl,
281	      timeoutMs,
282	      maxResponseBytes,
283	      options.userAgent ?? DEFAULT_USER_AGENT,
284	    );
285	  }
286	
287	  if (!fetchImpl) {
288	    throw new UrlIngestionError("network-error", "No fetch implementation is available.", {
289	      url: sourceUrl,
290	    });
291	  }
292	
293	  const controller = new AbortController();
294	  const timeout = setTimeout(() => controller.abort(), timeoutMs);
295	  let response: Response;
296	  let fetchedUrl = sourceUrl;
297	
298	  let xPost: XPostMetadata | null = null;
299	  if (parseXPostUrl(sourceUrl)) {
300	    try {
301	      const oEmbedResponse = await fetchImpl(xPostOEmbedUrl(sourceUrl), {
302	        headers: {
303	          Accept: "application/json",
304	          "User-Agent": options.userAgent ?? DEFAULT_USER_AGENT,
305	        },
306	        redirect: "follow",
307	        signal: controller.signal,
308	      });
309	
310	      if (oEmbedResponse.ok) {
311	        const oEmbedBody = await readResponseText(
312	          oEmbedResponse,
313	          Math.min(maxResponseBytes, 512 * 1024),
314	          sourceUrl,
315	        );
316	        try {
317	          xPost = normalizeXPostOEmbed(
318	            sourceUrl,
319	            JSON.parse(oEmbedBody) as Record<string, unknown>,
320	          );
321	        } catch {
322	          xPost = null;
323	        }
324	      }
325	    } catch {
326	      // X can block or rate-limit the oEmbed request. Fall through to the
327	      // normal page pipeline so capture still has a chance to succeed.
328	    }
329	  }
330	
331	  if (xPost) {
332	    clearTimeout(timeout);
333	    const text = xPost.text || `${xPost.authorName ?? "X"} post`;
334	    return {
335	      sourceUrl,
336	      fetchedUrl: sourceUrl,
337	      canonicalUrl: xPost.postUrl,
338	      title: xPost.authorName ? `${xPost.authorName}'s post` : "X post",
339	      description: text,
340	      author: xPost.authorName ?? "",
341	      publishedDate: xPost.publishedDate ?? null,
342	      html: xPost.embedHtml ?? "",
343	      text,
344	      imageUrls: [],
345	      imageDimensions: [],
346	      safeEmbeds: [],
347	      extractor: "fallback",
348	      social: xPost,
349	    };
350	  }
351	
352	  try {
353	    for (let redirectCount = 0; ; redirectCount++) {
354	      // codeql[js/request-forgery,javascript/ssrf]: This local-first desktop pipeline intentionally fetches user-selected public URLs. parseHttpUrl rejects non-HTTP(S), credentialed, and private-network destinations before this boundary, and redirect targets are validated before the next request.
355	      response = await fetchImpl(fetchedUrl, {
356	        headers: {
357	          Accept: "text/html,application/xhtml+xml;q=0.9,text/plain;q=0.5",
358	          "User-Agent": options.userAgent ?? DEFAULT_USER_AGENT,
359	        },
360	        redirect: "manual",
361	        signal: controller.signal,
362	      });
363	
364	      if (!isRedirectStatus(response.status)) break;
365	      if (redirectCount >= MAX_REDIRECTS) {
366	        throw new UrlIngestionError("redirect-error", "The page redirected too many times.", {
367	          url: fetchedUrl,
368	        });
369	      }
370	
371	      const location = response.headers.get("location");
372	      const redirectUrl = location ? normalizeHttpUrl(location, fetchedUrl) : null;
373	      if (!redirectUrl) {
374	        throw new UrlIngestionError(
375	          "redirect-error",
376	          "The page returned an invalid redirect destination.",
377	          {
378	            url: fetchedUrl,
379	          },
380	        );
381	      }
382	
383	      fetchedUrl = parseHttpUrl(redirectUrl, {
384	        allowPrivateNetwork: options.allowPrivateNetwork,
385	      }).toString();
386	    }
387	  } catch (cause) {
388	    clearTimeout(timeout);
389	    if (cause instanceof UrlIngestionError) throw cause;
390	    if (controller.signal.aborted) {
391	      throw new UrlIngestionError("timeout", "The page took too long to download.", {
392	        cause,
393	        url: sourceUrl,
394	      });
395	    }
396	    throw new UrlIngestionError("network-error", "The page could not be downloaded.", {
397	      cause,
398	      url: sourceUrl,
399	    });
400	  }
401	
402	  let rawHtml: string;
403	  try {
404	    if (!response.ok) {
405	      throw new UrlIngestionError("http-error", `The page returned HTTP ${response.status}.`, {
406	        status: response.status,
407	        url: sourceUrl,
408	      });
409	    }
410	
411	    const contentType = response.headers.get("content-type")?.toLowerCase() ?? "";
412	    if (
413	      contentType &&
414	      !contentType.includes("text/html") &&
415	      !contentType.includes("application/xhtml+xml") &&
416	      !contentType.startsWith("text/plain")
417	    ) {
418	      throw new UrlIngestionError(
419	        "unsupported-content-type",
420	        "The URL did not return an HTML document.",
421	        {
422	          url: fetchedUrl,
423	        },
424	      );
425	    }
426	
427	    rawHtml = await readResponseText(response, maxResponseBytes, fetchedUrl);
428	  } catch (error) {
429	    if (error instanceof UrlIngestionError) throw error;
430	    if (controller.signal.aborted) {
431	      throw new UrlIngestionError("timeout", "The page took too long to download.", {
432	        cause: error,
433	        url: fetchedUrl,
434	      });
435	    }
436	    throw new UrlIngestionError("network-error", "The page could not be read.", {
437	      cause: error,
438	      url: fetchedUrl,
439	    });
440	  } finally {
441	    clearTimeout(timeout);
442	  }
443	
444	  const sourceDocument = parseDocument(rawHtml);
445	  const extractionDocument = parseDocument(rawHtml);
446	  promoteInfoAsides(extractionDocument);
447	  const fallback = extractFallback(sourceDocument, fetchedUrl);
448	  const adapter = options.defuddleAdapter ?? new DefaultDefuddleAdapter();
449	  let extraction = fallback;
450	  let extractor: "defuddle" | "fallback" = "fallback";
451	
452	  try {
453	    const defuddleExtraction = await adapter.extract(extractionDocument, fetchedUrl);
454	    extraction = mergeExtraction(defuddleExtraction, fallback);
455	    if (hasReadableText(defuddleExtraction.contentHtml)) extractor = "defuddle";
456	  } catch {
457	    extraction = fallback;
458	  }
459	
460	  const byline = visibleByline(sourceDocument);
461	  if (byline.author) extraction = { ...extraction, author: byline.author };
462	  if (byline.publishedDate) extraction = { ...extraction, publishedDate: byline.publishedDate };
463	
464	  const title = normalizeText(extraction.title) || new URL(fetchedUrl).hostname;
465	  const description = normalizeText(extraction.description);
466	  const contentDocument = parseDocument(
467	    `<html><head></head><body>${sanitizeHtml(extraction.contentHtml ?? "", fetchedUrl)}</body></html>`,
468	  );
469	  const html = cleanArticleHeadings(contentDocument, title, description);
470	  if (!hasReadableText(html)) {
471	    throw new UrlIngestionError(
472	      "extraction-failed",
473	      "No readable article content was found on the page.",
474	      {
475	        url: fetchedUrl,
476	      },
477	    );
478	  }
479	
480	  const canonicalUrl = normalizeHttpUrl(extraction.canonicalUrl, fetchedUrl) ?? fetchedUrl;
481	  const imageUrls = uniqueStrings([
482	    ...collectImageUrls(sourceDocument, fetchedUrl),
483	    ...(extraction.imageUrls ?? [])
484	      .map((value) => normalizeHttpUrl(value, fetchedUrl))
485	      .filter((value): value is string => value !== null),
486	  ]);
487	  const imageDimensions = (extraction.imageDimensions ?? [])
488	    .map((value) => {
489	      const url = normalizeHttpUrl(value.url, fetchedUrl);
490	      return url ? { ...value, url } : null;
491	    })
492	    .filter(
493	      (value, index, values): value is NonNullable<typeof value> =>
494	        value !== null &&
495	        imageUrls.includes(value.url) &&
496	        values.findIndex((candidate) => candidate?.url === value.url) === index,
497	    );
498	
499	  return {
500	    sourceUrl,
501	    fetchedUrl,
502	    canonicalUrl,
503	    title,
504	    description,
505	    author: normalizeText(extraction.author),
506	    publishedDate: normalizePublishedDate(extraction.publishedDate),
507	    html,
508	    text: htmlToText(html),
509	    imageUrls,
510	    imageDimensions,
511	    safeEmbeds: collectSafeEmbeds(sourceDocument, fetchedUrl),
512	    extractor,
513	  };
514	}
