14	/**
15	 * Native Windows OCR (Windows.Media.Ocr) invoked through Windows PowerShell
16	 * 5.1, which is the only host that can project WinRT types. Zero-install on
17	 * any Windows machine with the OCR language pack.
18	 */
19	export class WindowsOcrEngine implements OcrEngine {
20	  name = "windows-ocr";
21	  private checked = false;
22	  private ready = false;
23	
24	  constructor(private readonly scriptPath: string) {}
25	
26	  async available(): Promise<boolean> {
27	    if (this.checked) return this.ready;
28	    this.checked = true;
29	    if (process.platform !== "win32") return false;
30	    try {
31	      const result = Bun.spawnSync([
32	        "powershell.exe",
33	        "-NoProfile",
34	        "-Command",
35	        "& { $null = [Windows.Media.Ocr.OcrEngine, Windows.Foundation, ContentType=WindowsRuntime]; exit 0 }",
36	      ]);
37	      this.ready = result.exitCode === 0;
38	    } catch {
39	      this.ready = false;
40	    }
41	    return this.ready;
42	  }
43	
44	  async run(imagePath: string | Uint8Array): Promise<string> {
45	    let temporaryDirectory: string | null = null;
46	    try {
47	      let sourcePath: string;
48	      if (typeof imagePath === "string") {
49	        sourcePath = imagePath;
50	      } else {
51	        temporaryDirectory = mkdtempSync(join(tmpdir(), "inkling-windows-ocr-"));
52	        sourcePath = join(temporaryDirectory, "page.png");
53	        writeFileSync(sourcePath, imagePath);
54	      }
55	      const result = Bun.spawnSync(
56	        [
57	          "powershell.exe",
58	          "-NoProfile",
59	          "-ExecutionPolicy",
60	          "Bypass",
61	          "-File",
62	          this.scriptPath,
63	          "-ImagePath",
64	          sourcePath,
65	        ],
66	        { stdout: "pipe", stderr: "pipe" },
67	      );
68	      if (result.exitCode !== 0) {
69	        throw new Error(
70	          `Windows OCR failed (exit ${result.exitCode}): ${result.stderr.toString("utf8")}`,
71	        );
72	      }
73	      return result.stdout.toString("utf8").trim();
74	    } finally {
75	      if (temporaryDirectory) rmSync(temporaryDirectory, { recursive: true, force: true });
76	    }
77	  }
78	}
